(() => {

    window.dikcizPresetRoots ||= new WeakSet();
    window.dikcizPresetWrite ||= (key, value) => selfWidget.item(key).patchState(value);

    const initialize = () => document.querySelectorAll('[data-dikciz-preset="command-deck"]').forEach(root => {
        if (window.dikcizPresetRoots.has(root)) return;
        window.dikcizPresetRoots.add(root);
        const stateKey = root.getAttribute("data-dikciz-item-id");
        const onReady = listener => {
            if (window.selfWidget && window.dikciz) listener();
            else window.addEventListener("dikciz-ready", listener, {once:true});
        };

    const MINUTE_MS = 60000;
    const status = root.querySelector('[data-role="status"]');
    let ready = false;
    function renderClock() {
        const now = new Date();
        const clock = root.querySelector('[data-role="clock"]');
        const date = root.querySelector('[data-role="date"]');
        if (clock) clock.textContent = now.toLocaleTimeString([], {hour:"2-digit", minute:"2-digit"});
        if (date) date.textContent = now.toLocaleDateString([], {weekday:"long", month:"long", day:"numeric"});
    }
    renderClock();
    const timer = setInterval(() => { if (!root.isConnected) { clearInterval(timer); return; } if (!document.hidden) renderClock(); }, MINUTE_MS);
    document.addEventListener("visibilitychange", () => { if (root.isConnected) renderClock(); });
    onReady( () => { ready = true; });
    root.querySelector('[data-role="search"]')?.addEventListener("submit", async event => {
        event.preventDefault();
        const query = root.querySelector('[data-role="query"]').value.trim();
        if (!query || !ready) return;
        try {
            const result = await dikciz.command("intent", {
                intentType:"activity", action:"android.intent.action.VIEW",
                data:"https://www.google.com/search?q=" + encodeURIComponent(query)
            });
            const launch = result.activityLaunches?.[0];
            status.textContent = launch?.verified ? "Browser opened." : "Browser requested. " + (launch?.reason || "Check Android for the result.");
        } catch (error) { status.textContent = "Search unavailable: " + error.message; }
    });

    });
    initialize();
    window.addEventListener("dikciz-block-appended", initialize);
})();
(() => {

    window.dikcizPresetRoots ||= new WeakSet();
    window.dikcizPresetWrite ||= (key, value) => selfWidget.item(key).patchState(value);

    const initialize = () => document.querySelectorAll('[data-dikciz-preset="quick-apps"]').forEach(root => {
        if (window.dikcizPresetRoots.has(root)) return;
        window.dikcizPresetRoots.add(root);
        const stateKey = root.getAttribute("data-dikciz-item-id");
        const onReady = listener => {
            if (window.selfWidget && window.dikciz) listener();
            else window.addEventListener("dikciz-ready", listener, {once:true});
        };

    const MAX_VISIBLE = 6;
    const status = root.querySelector('[data-role="status"]');
    const list = root.querySelector('[data-role="apps"]');
    const iconCache = new Map();
    let apps = [];
    let launching = false;
    function render() {
        if (!list) return;
        list.replaceChildren();
        const query = root.querySelector('[data-role="app-query"]')?.value.trim().toLocaleLowerCase() || "";
        const matches = apps.filter(app => (app.label + " " + app.packageName).toLocaleLowerCase().includes(query));
        matches.slice(0, MAX_VISIBLE).forEach(app => {
            const button = document.createElement("button");
            button.type = "button";
            button.className = "secondary";
            const label = document.createElement("span");
            label.textContent = app.label;
            const icon = document.createElement("img");
            icon.width = 40;
            icon.height = 40;
            icon.alt = "";
            icon.hidden = true;
            button.append(icon, label);
            if (!iconCache.has(app.component)) {
                iconCache.set(app.component, dikciz.command("appIcon", {component:app.component, sizePixels:64}));
            }
            iconCache.get(app.component).then(result => {
                if (!button.isConnected) return;
                icon.src = "data:image/png;base64," + result.pngBase64;
                icon.hidden = false;
            }).catch(error => {
                iconCache.delete(app.component);
                button.title = "Icon unavailable: " + error.message;
            });
            button.addEventListener("click", async () => {
                if (launching) return;
                launching = true;
                button.disabled = true;
                status.textContent = "Opening " + app.label + "...";
                try {
                    const result = await dikciz.command("appAction", {action:"launch", component:app.component});
                    const launch = result.activityLaunches?.[0];
                    status.textContent = launch?.verified ? app.label + " opened." : "Launch unverified: " + (launch?.reason || result.outcome || "Check Android.");
                } catch (error) { status.textContent = "Could not open app: " + error.message; }
                finally { launching = false; button.disabled = false; }
            });
            list.append(button);
        });
        status.textContent = matches.length ? "Showing " + Math.min(matches.length, MAX_VISIBLE) + " of " + matches.length + ". Tap an app to launch it. Drawer shortcuts are separate home-screen widgets." : "No matching installed apps.";
    }
    root.querySelector('[data-role="app-query"]')?.addEventListener("input", render);
    onReady( async () => {
        try {
            const result = await dikciz.command("appCatalogue");
            apps = Array.isArray(result.apps) ? result.apps : [];
            render();
        } catch (error) { status.textContent = "Apps unavailable: " + error.message; }
    });

    });
    initialize();
    window.addEventListener("dikciz-block-appended", initialize);
})();
(() => {

    window.dikcizPresetRoots ||= new WeakSet();
    window.dikcizPresetWrite ||= (key, value) => selfWidget.item(key).patchState(value);

    const initialize = () => document.querySelectorAll('[data-dikciz-preset="quick-note"]').forEach(root => {
        if (window.dikcizPresetRoots.has(root)) return;
        window.dikcizPresetRoots.add(root);
        const stateKey = root.getAttribute("data-dikciz-item-id");
        const onReady = listener => {
            if (window.selfWidget && window.dikciz) listener();
            else window.addEventListener("dikciz-ready", listener, {once:true});
        };

    const MAX_NOTE_LENGTH = 2000;
    const note = root.querySelector('[data-role="note"]');
    const button = root.querySelector('[data-role="save"]');
    const status = root.querySelector('[data-role="status"]');
    let dirty = false;
    function render(state) {
        if (note && !dirty) note.value = typeof state.text === "string" ? state.text.slice(0, MAX_NOTE_LENGTH) : "";
    }
    note?.addEventListener("input", () => { dirty = true; status.textContent = "Unsaved changes. Tap Save note."; });
    onReady( () => render((selfWidget.itemStates[stateKey] || {})));
    window.addEventListener("dikciz-item-state", event => render(event.detail?.[stateKey] || {}));
    button?.addEventListener("click", async () => {
        const text = note.value.slice(0, MAX_NOTE_LENGTH);
        button.disabled = true;
        try {
            await window.dikcizPresetWrite(stateKey, {text});
            dirty = note.value !== text;
            status.textContent = dirty ? "New changes are not saved yet." : "Note saved on this phone.";
        } catch (error) { status.textContent = "Note not saved: " + error.message; }
        finally { button.disabled = false; }
    });

    });
    initialize();
    window.addEventListener("dikciz-block-appended", initialize);
})();

(() => {
    const REQUEST_TIMEOUT_MS = 15000;
    const MAX_RESPONSE_BYTES = 65536;
    const CITY_LIMIT = 5;
    const LOCATION_MAX_AGE_MS = 300000;
    const WEATHER_MAX_AGE_MS = 15 * 60 * 1000;
    const LOCATION_TIMEOUT_MS = 10000;
    const locateButton = document.getElementById("locate");
    const status = document.getElementById("status");
    const choices = document.getElementById("choices");
    const refreshButton = document.getElementById("refresh");
    const findButton = document.getElementById("find");
    let state = {};
    let busy = false;
    let ready = false;
    const text = (id, value) => { const node = document.getElementById(id); if (node) node.textContent = value; };
    const number = (value, suffix) => Number.isFinite(value) ? Math.round(value) + suffix : "Unavailable";
    const validCity = city => city && typeof city.name === "string" && city.name.length <= 120 && Number.isFinite(city.latitude) && Math.abs(city.latitude) <= 90 && Number.isFinite(city.longitude) && Math.abs(city.longitude) <= 180;
    function setBusy(value) {
        busy = value;
        findButton.disabled = value;
        locateButton.disabled = value;
        refreshButton.disabled = value || !validCity(state.city);
        choices?.querySelectorAll("button").forEach(button => { button.disabled = value; });
    }
    async function request(url) {
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
        try {
            const response = await fetch(url, {signal:controller.signal, credentials:"omit", referrerPolicy:"no-referrer"});
            if (!response.ok) throw new Error("Service returned HTTP " + response.status);
            const reader = response.body.getReader();
            const chunks = [];
            let length = 0;
            while (true) {
                const chunk = await reader.read();
                if (chunk.done) break;
                length += chunk.value.byteLength;
                if (length > MAX_RESPONSE_BYTES) {
                    await reader.cancel();
                    throw new Error("Service response is too large.");
                }
                chunks.push(chunk.value);
            }
            const bytes = new Uint8Array(length);
            let offset = 0;
            for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
            const result = JSON.parse(new TextDecoder().decode(bytes));
            if (!result || typeof result !== "object" || Array.isArray(result) || result.error) throw new Error("Invalid service response.");
            return result;
        } finally { clearTimeout(timeout); }
    }
    function render() {
        text("place", validCity(state.city) ? state.city.name : "Choose your city");
        const weather = state.weather || {};
        text("temperature", number(weather.temperature, "°C"));
        text("feels", number(weather.feels, "°C"));
        text("wind", number(weather.wind, ""));
        text("rain", number(weather.rain, "%"));
        text("range", Number.isFinite(weather.low) && Number.isFinite(weather.high) ? Math.round(weather.low) + " / " + Math.round(weather.high) + "°" : "Unavailable");
        text("aqi", number(state.air?.aqi, ""));
        text("weather-status", weather.fetchedAt ? "Saved weather, fetched " + new Date(weather.fetchedAt).toLocaleString() + ". Refresh for current data." : "Weather has not been loaded.");
        text("air-status", state.air?.fetchedAt ? "Saved air data, fetched " + new Date(state.air.fetchedAt).toLocaleString() + ". Lower AQI means cleaner air." : "Air quality has not been loaded.");
        setBusy(busy);
    }
    async function refresh() {
        if (busy || !selfWidget.visible || !validCity(state.city)) return;
        setBusy(true);
        status.textContent = "Fetching weather and air quality...";
        const city = {...state.city};
        let weather = state.weather || {};
        let air = state.air || {};
        const location = "latitude=" + encodeURIComponent(city.latitude) + "&longitude=" + encodeURIComponent(city.longitude);
        try {
            const results = await Promise.allSettled([
                request("https://api.open-meteo.com/v1/forecast?" + location + "&current=temperature_2m,apparent_temperature,wind_speed_10m&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max&forecast_days=1&timezone=auto"),
                request("https://air-quality-api.open-meteo.com/v1/air-quality?" + location + "&current=european_aqi&forecast_days=1")
            ]);
            const errors = [];
            if (results[0].status === "fulfilled" && Number.isFinite(results[0].value.current?.temperature_2m)) {
                const data = results[0].value;
                weather = {temperature:data.current.temperature_2m, feels:data.current.apparent_temperature, wind:data.current.wind_speed_10m, high:data.daily?.temperature_2m_max?.[0], low:data.daily?.temperature_2m_min?.[0], rain:data.daily?.precipitation_probability_max?.[0], fetchedAt:Date.now()};
            } else { errors.push("Weather unavailable"); }
            if (results[1].status === "fulfilled" && Number.isFinite(results[1].value.current?.european_aqi)) {
                air = {aqi:results[1].value.current.european_aqi, fetchedAt:Date.now()};
            } else { errors.push("Air quality unavailable"); }
            const nextState = {city, weather, air};
            await selfWidget.patchState(nextState);
            state = nextState;
            render();
            status.textContent = errors.length ? errors.join(". ") + ". Saved readings are shown when available. Try Refresh weather." : "Saved latest readings. Refresh when needed.";
        } catch (error) { status.textContent = "Could not save readings: " + error.message; }
        finally { setBusy(false); }
    }
    document.getElementById("city-search")?.addEventListener("submit", async event => {
        event.preventDefault();
        if (busy) return;
        const query = document.getElementById("city").value.trim();
        if (query.length < 2) { status.textContent = "Enter at least two characters."; return; }
        setBusy(true);
        choices.replaceChildren();
        status.textContent = "Searching cities...";
        try {
            const data = await request("https://geocoding-api.open-meteo.com/v1/search?name=" + encodeURIComponent(query) + "&count=" + CITY_LIMIT + "&language=en&format=json");
            const cities = Array.isArray(data.results) ? data.results.slice(0, CITY_LIMIT) : [];
            for (const result of cities) {
                const city = {name:[result.name, result.admin1, result.country].filter(value => typeof value === "string").join(", ").slice(0,120), latitude:result.latitude, longitude:result.longitude};
                if (!validCity(city)) continue;
                const button = document.createElement("button");
                button.type = "button";
                button.className = "secondary";
                button.textContent = city.name;
                button.addEventListener("click", async () => {
                    if (busy) return;
                    setBusy(true);
                    try {
                        await selfWidget.patchState({city, weather:{}, air:{}});
                        state = {city};
                        choices.replaceChildren();
                        render();
                    } catch (error) {
                        status.textContent = "Could not save city: " + error.message;
                        setBusy(false);
                        return;
                    }
                    setBusy(false);
                    await refresh();
                });
                choices.append(button);
            }
            status.textContent = choices.children.length ? "Choose the matching city." : "No matching cities. Try another name.";
        } catch (error) { status.textContent = "City search unavailable. Check your connection and retry."; }
        finally { setBusy(false); }
    });
    async function locate() {
        if (busy || !selfWidget.visible) return;
        setBusy(true);
        status.textContent = "Finding your phone location...";
        try {
            const location = await dikciz.command("locationGet", {
                maxAgeMilliseconds:LOCATION_MAX_AGE_MS, timeoutMilliseconds:LOCATION_TIMEOUT_MS,
                autoRequestPermissions:true
            });
            if (!location.available) {
                status.textContent = "Location unavailable: " + location.reason + ". Try Use my location again or choose a city.";
                return;
            }
            const city = {
                name:(location.placeName || "Current location (" + location.latitude.toFixed(2) + ", " + location.longitude.toFixed(2) + ")").slice(0,120),
                latitude:location.latitude, longitude:location.longitude, source:"device", locatedAt:Date.now()
            };
            if (!validCity(city)) throw new Error("Phone returned invalid coordinates.");
            await selfWidget.patchState({city, weather:{}, air:{}});
            state = {city};
            choices.replaceChildren();
            render();
        } catch (error) {
            status.textContent = "Location needs attention: " + (error.message || error.code || "unavailable") + ". Review access on your phone, then tap Use my location, or choose a city.";
            return;
        } finally { setBusy(false); }
        await refresh();
    }
    locateButton.addEventListener("click", locate);
    refreshButton?.addEventListener("click", refresh);
    function activate() {
        if (!ready || !window.selfWidget?.visible || busy) return;
        if (!validCity(state.city) || (state.city.source === "device" && Date.now() - (state.city.locatedAt || 0) > LOCATION_MAX_AGE_MS)) {
            locate().catch(error => { status.textContent = "Location failed: " + error.message; });
            return;
        }
        status.textContent = "Saved city and readings. Tap Refresh weather to update.";
        if (!state.weather?.fetchedAt || Date.now() - state.weather.fetchedAt > WEATHER_MAX_AGE_MS) {
            refresh().catch(error => { status.textContent = "Weather refresh failed: " + error.message; });
        }
    }
    window.addEventListener("dikciz-ready", () => {
        state = selfWidget.state || {};
        ready = true;
        render();
        activate();
    });
    window.addEventListener("dikciz-visibility", event => {
        if (event.detail.visible && window.selfWidget) activate();
    });
    window.addEventListener("dikciz-state", event => {
        state = event.detail || {};
        render();
    });
})();

(() => {
    const status = document.getElementById("status");
    const button = document.getElementById("refresh");
    async function refresh() {
        button.disabled = true;
        try {
            const state = await dikciz.command("deviceState");
            const known = Number.isFinite(state.batteryLevel) && state.batteryLevel >= 0 && Number.isFinite(state.batteryScale) && state.batteryScale > 0;
            const battery = document.getElementById("battery");
            const power = document.getElementById("power");
            const network = document.getElementById("network");
            const connection = document.getElementById("connection");
            if (battery) battery.textContent = known ? Math.round(state.batteryLevel * 100 / state.batteryScale) + "%" : "Unknown";
            if (power) power.textContent = state.chargingSource > 0 ? "Plugged in" : "On battery";
            if (network) network.textContent = state.vpn ? "VPN" : state.wifi ? "Wi-Fi" : state.cellular ? "Mobile" : state.networkAvailable ? "Network" : "Offline";
            if (connection) connection.textContent = state.internetValidated ? "Android confirms internet" : "Internet not confirmed";
            status.textContent = "Updated " + new Date().toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"}) + (state.powerSaveMode ? ". Battery saver is on." : ". Battery saver is off.");
        } catch (error) { status.textContent = "Phone data unavailable: " + error.message; }
        finally { button.disabled = false; }
    }
    button?.addEventListener("click", refresh);
    window.addEventListener("dikciz-ready", refresh);
})();

(() => {
    const POLL_MS = 1500;
    const SAMPLE_MS = 500;
    const PAGE_SIZE = 200;
    const status = document.getElementById("status");
    const container = document.getElementById("sensors");
    const toggle = document.getElementById("toggle");
    const cards = new Map();
    let timer;
    let busy = false;
    let ready = false;
    let paused = false;
    function render(sensor) {
        let nodes = cards.get(sensor.sensorId);
        if (!nodes) {
            const article = document.createElement("section");
            article.className = "card";
            const title = document.createElement("h2");
            const description = document.createElement("p");
            const values = document.createElement("pre");
            const detail = document.createElement("p");
            const permission = document.createElement("button");
            permission.type = "button";
            permission.textContent = "Review sensor access";
            permission.addEventListener("click", async () => {
                try {
                    const result = await dikciz.command("requestDeviceAccess", {requirementId:permission.dataset.requirementId});
                    status.textContent = result.instructions || "Review access on your phone, then return here.";
                } catch (error) { status.textContent = "Access request failed: " + error.message; }
            });
            article.append(title, description, values, detail, permission);
            container.append(article);
            nodes = {article, title, description, values, detail, permission};
            cards.set(sensor.sensorId, nodes);
        }
        nodes.title.textContent = sensor.name;
        nodes.description.textContent = "ID " + sensor.sensorId + " · " + sensor.stringType + " · " + sensor.vendor;
        nodes.values.textContent = sensor.available
            ? sensor.values.map((value, index) => "[" + index + "] " + (Number.isFinite(value) ? value.toFixed(4) : "unavailable")).join("\n")
            : (sensor.reason || "Unavailable").replaceAll("_", " ");
        nodes.detail.textContent = "Mode " + sensor.reportingMode + " · " + (sensor.available
            ? "Accuracy " + sensor.accuracy + " · sample age " + sensor.ageMilliseconds + " ms"
            : "No reading reported by Android") + " · range " + sensor.maximumRange + " · resolution " + sensor.resolution;
        nodes.permission.dataset.requirementId = sensor.requirementId || "";
        nodes.permission.hidden = !sensor.requirementId;
    }
    async function refresh() {
        clearTimeout(timer);
        if (!ready || busy || paused || document.hidden || !window.dikciz || !window.selfWidget?.visible) return;
        busy = true;
        try {
            const seen = new Set();
            let offset = 0;
            let available = 0;
            let more;
            do {
                const result = await dikciz.command("sensorReadings", {offset, limit:PAGE_SIZE, timeoutMilliseconds:SAMPLE_MS});
                for (const sensor of result.items) {
                    seen.add(sensor.sensorId);
                    render(sensor);
                    if (sensor.available) available++;
                }
                offset += result.items.length;
                more = result.hasMore && result.items.length > 0;
            } while (more && !document.hidden && !paused);
            if (!more) {
                for (const [id, nodes] of cards) {
                    if (seen.has(id)) continue;
                    nodes.article.remove();
                    cards.delete(id);
                }
            }
            status.textContent = offset + " sensors, " + available + " with readings. Updated " + new Date().toLocaleTimeString() +
                ". Values use Android sensor units. Trigger sensors wait for their event.";
        } catch (error) {
            status.textContent = "Sensor sampling failed: " + error.message + ". Previous readings may be stale.";
        } finally {
            busy = false;
            if (!paused && !document.hidden && window.selfWidget?.visible) timer = setTimeout(refresh, POLL_MS);
        }
    }
    toggle.addEventListener("click", () => {
        paused = !paused;
        toggle.textContent = paused ? "Resume" : "Pause";
        clearTimeout(timer);
        if (!paused) refresh();
        else status.textContent = "Sampling paused. Displayed values are from the last sample.";
    });
    window.addEventListener("dikciz-ready", () => { ready = true; refresh(); });
    window.addEventListener("dikciz-visibility", event => {
        clearTimeout(timer);
        if (event.detail.visible) refresh();
    });
    document.addEventListener("visibilitychange", () => {
        clearTimeout(timer);
        if (!document.hidden) refresh();
    });
    window.addEventListener("pagehide", () => { paused = true; clearTimeout(timer); });
})();

